function pdfDownloads(ids){const guides=ids?pdfGuides.filter(p=>ids.includes(p.id)):pdfGuides;return `<section class="pdf-downloads" aria-labelledby="pdf-download-heading"><div class="section-top"><div><h2 id="pdf-download-heading">Take your learning offline</h2><p>Original NxGenVarsity guides and printable workbooks. Free PDF downloads.</p></div><span class="pdf-series-label">NXGENVARSITY FIELDNOTES</span></div><div class="resource-grid">${guides.map(p=>`<article class="resource-card pdf-card" data-tone="${p.tone}"><div class="pdf-card-top"><img src="assets/nxgenvarsity-logo.png" alt="NxGenVarsity" width="130" height="23"><span class="pdf-format">PDF</span></div><h3>${p.title}</h3><p>${p.description}</p><div class="tags"><span class="tag">${p.pages} pages</span><span class="tag">${p.sizeLabel}</span><span class="tag">Print-friendly</span></div><div class="resource-actions"><a class="btn small pdf-download-btn" href="${p.url}" download type="application/pdf" aria-label="Download ${p.title} PDF">Download PDF <span aria-hidden="true">↓</span></a><a class="text-link" href="${p.url}" target="_blank" rel="noopener noreferrer" type="application/pdf" aria-label="Preview ${p.title} PDF">Preview ↗</a></div></article>`).join('')}</div></section>`;}
